// Keep the lightweight first arrival synchronized without loading the engine.
import fs from 'node:fs';
import {loadEngine} from '../tests/helpers/load-engine.mjs';

const M = loadEngine();
const counts = {
  decks: Object.values(M.DECKS).filter(deck => !deck.custom).length,
  importableCards: Object.values(M.CARD_CATALOG).filter(card => card.deckImportEligible).length,
};
fs.writeFileSync(new URL('../src/catalog-summary.js', import.meta.url),
  "// Generated by node scripts/sync-landing-counts.mjs after catalog changes.\n'use strict';\nvar MTG = globalThis.MTG || (globalThis.MTG = {});\nMTG.CATALOG_SUMMARY = Object.freeze(" + JSON.stringify(counts) + ');\n');
const index = new URL('../index.html', import.meta.url);
fs.writeFileSync(index, fs.readFileSync(index, 'utf8')
  .replace(/with \d+ tested decks/, `with ${counts.decks} tested decks`)
  .replace(/(<span data-catalog-decks>)\d+(<\/span>)/g, `$1${counts.decks}$2`)
  .replace(/Explore all \d+ Commander decks/g, `Explore all ${counts.decks} Commander decks`));
console.log(JSON.stringify(counts));
